@lru_cache(maxsize=32768)
def normalizar(texto):
    """Devuelve el texto sin acentos, mayúsculas ni marcas comerciales."""
    limpio = texto.replace("®", "").replace("™", "").replace("©", "").casefold()
    letras = unicodedata.normalize("NFKD", limpio)
    letras = "".join(c for c in letras if not unicodedata.combining(c))
    return " ".join(re.findall(r"[^\W_]+", letras, re.UNICODE))


def clave_titulo(titulo):
    """Identifica el título base y las ediciones equivalentes documentadas."""
    clave = normalizar(titulo)
    return EDICIONES_EQUIVALENTES.get(clave, clave)


def numero(texto):
    """Convierte texto numérico no negativo en un flotante o devuelve None."""
    valor = None
    try:
        medido = float(texto)
        if math.isfinite(medido) and medido >= 0:
            valor = medido
    except (TypeError, ValueError):
        valor = None
    return valor


def nombres_de_campo(texto):
    """Devuelve valores limpios de una lista textual o de un arreglo JSON."""
    valores = re.split(r"[;,|]", texto)
    if texto.startswith("[") and texto.endswith("]"):
        try:
            arreglo = json.loads(texto)
        except json.JSONDecodeError:
            # Algunas exportaciones usan comillas simples en las listas.
            arreglo = re.split(r"[;,|]", texto[1:-1])
        if isinstance(arreglo, list):
            valores = [v for v in arreglo if isinstance(v, str)]
    return [v.strip(" '\"") for v in valores if v.strip(" '\"")]


def etiquetas_de_campo(texto):
    """Devuelve hasta ocho etiquetas. En JSON con recuentos prioriza los votos."""
    if texto.startswith("{") and texto.endswith("}"):
        try:
            recuentos = json.loads(texto)
        except json.JSONDecodeError:
            recuentos = {}
        valores = sorted(recuentos, key=lambda clave: -(numero(recuentos[clave]) or 0))
    else:
        valores = nombres_de_campo(texto)
    return valores[:8]


@dataclass(frozen=True)
class FuenteCatalogo:
    """Identifica un CSV por nombre y, si es externo, por su ruta local."""

    nombre: str
    ruta: Path | None = None

    def firma(self):
        """Devuelve los metadatos usados para invalidar el ajuste guardado."""
        if self.ruta is None:
            firma = (self.nombre, len(DATOS_INCLUIDOS[self.nombre]), VERSION_DATOS)
        else:
            datos = self.ruta.stat()
            firma = (str(self.ruta.resolve()), datos.st_size, datos.st_mtime_ns)
        return firma


@contextmanager
def abrir_csv(fuente):
    """Abre un CSV UTF-8 externo o incluido en ZIP, sin extraerlo al disco."""
    if fuente.ruta is not None and fuente.ruta.suffix.lower() == ".csv":
        with fuente.ruta.open(encoding="utf-8-sig", newline="") as datos:
            yield datos
    else:
        origen = fuente.ruta
        if origen is None:
            origen = BytesIO(base64.b64decode(DATOS_INCLUIDOS[fuente.nombre]))
        with zipfile.ZipFile(origen) as comprimido:
            nombres = [n for n in comprimido.namelist()
                       if n.lower().endswith(".csv") and not n.startswith("__MACOSX/")]
            preferido = Path(fuente.nombre).stem.removesuffix(".csv") + ".csv"
            exactos = [n for n in nombres if Path(n).name.casefold() == preferido.casefold()]
            elegibles = exactos or nombres
            if len(elegibles) != 1:
                raise ValueError(f"{fuente.nombre} debe identificar un solo CSV de videojuegos.")
            with comprimido.open(elegibles[0]) as binario:
                with TextIOWrapper(binario, encoding="utf-8-sig", newline="") as datos:
                    yield datos


def localizar_catalogos(carpeta):
    """Selecciona las fuentes disponibles, dando prioridad a las copias locales."""
    principal = (f"{NOMBRE_VENTAS}.csv.zip", f"{NOMBRE_VENTAS}.csv")
    complementario = ("games.csv.zip", "games.csv", "games.zip")
    fuentes = []
    for nombres in (principal, complementario):
        ruta = next((carpeta / n for n in nombres if (carpeta / n).is_file()), None)
        if ruta is not None:
            fuentes.append(FuenteCatalogo(ruta.name, ruta))
        elif nombres[0] in DATOS_INCLUIDOS:
            fuentes.append(FuenteCatalogo(nombres[0]))
    return fuentes


@dataclass
class Videojuego:
    """Ficha unificada. La nota pública y la popularidad se escalan a [0, 1]."""

    titulo: str
    anio: int | None = None
    saga: str = ""
    generos: set = field(default_factory=set)
    plataformas: set = field(default_factory=set)
    atributos: set = field(default_factory=set)
    calidad_publica: float = 0.65
    evidencia_publica: float = 0.0  # Número de opiniones, cuando se conoce.
    popularidad: float = 0.0       # Logaritmo escalado de ventas o reseñas.

    @property
    def referencia(self):
        """Combina calidad y popularidad públicas para el arranque del perfil."""
        return 0.80 * self.calidad_publica + 0.20 * self.popularidad


def resena_publica(fila):
    """Devuelve calidad suavizada, cantidad de opiniones y popularidad."""
    positivas = numero(fila["positivas"])
    negativas = numero(fila["negativas"])
    votos = 0.0
    nota = None
    ventas = numero(fila["ventas"])
    if positivas is not None and negativas is not None:
        votos = positivas + negativas
        if votos:
            nota = (positivas + 13) / (votos + 20)
    else:
        nota_usuario = numero(fila["nota"])
        critica = numero(fila["critica"])
        if nota_usuario is not None and 0 <= nota_usuario <= 10:
            # Las notas con pocas opiniones se acercan a la referencia 0.65.
            votos = numero(fila["usuarios"]) or 1.0
            nota = (votos * nota_usuario / 10 + 13) / (votos + 20)
        elif critica is not None and 0 < critica <= 100:
            votos = 0.5  # La crítica actúa como señal de respaldo.
            nota = 0.5 * (critica / 100 + 0.65)
    popularidad = 0.0
    if ventas is not None:
        popularidad = min(1.0, math.log1p(ventas) / math.log1p(30))
    elif positivas is not None and negativas is not None:
        popularidad = min(1.0, math.log1p(votos) / math.log1p(25000))
    return nota, votos, popularidad


class Catalogo:
    """Índice de fichas, identificadores de Steam y plataformas conocidas."""

    def __init__(self, fuentes):
        """Recibe una secuencia de fuentes de catálogo incluidas o externas."""
        self.fuentes = tuple(fuentes)
        self.juegos = {}
        self.por_appid = {}
        self.estadisticas = {}
        limite_anterior = csv.field_size_limit(32 * 1024 * 1024)
        try:
            for fuente in self.fuentes:
                self.leer(fuente)
        finally:
            csv.field_size_limit(limite_anterior)
        if not self.juegos:
            raise ValueError("Los archivos no contienen títulos utilizables.")
        self.plataformas = {normalizar(p): p for j in self.juegos.values() for p in sorted(j.plataformas)}

    def leer(self, fuente):
        """Añade filas de un CSV según sus columnas y registra altas y coincidencias."""
        total = altas = coincidencias = 0
        with abrir_csv(fuente) as datos:
            encabezado = datos.readline()
            delimitador = max((",", ";", "\t"), key=lambda d: len(next(csv.reader([encabezado], delimiter=d))))
            nombres = next(csv.reader([encabezado], delimiter=delimitador))
            lector = csv.reader(datos, delimiter=delimitador)
            primera = next((valores for valores in lector if valores), [])

            # En la exportación CSV 59 de Steam, dos nombres de columna
            # aparecen unidos aunque cada fila tenga ambos valores.
            if "DiscountDLC count" in nombres and len(primera) == len(nombres) + 1:
                indice = nombres.index("DiscountDLC count")
                nombres[indice:indice + 1] = ["Discount", "DLC count"]
            disponibles = {normalizar(columna): columna for columna in nombres}
            campos = {
                destino: next((disponibles[a] for a in alias if a in disponibles), None)
                for destino, alias in COLUMNAS.items()
            }
            if campos["titulo"] is None:
                raise ValueError(f"{fuente.nombre} necesita una columna Name, Title o titulo.")
            for valores in chain((primera,), lector):
                if valores:
                    if len(valores) > len(nombres):
                        raise ValueError(f"{fuente.nombre} contiene una fila con columnas adicionales.")
                    total += 1
                    cruda = dict(zip(nombres, valores))
                    fila = {destino: cruda.get(campo, "").strip() for destino, campo in campos.items()}
                    clave = clave_titulo(fila["titulo"])
                    if clave:
                        existe = clave in self.juegos
                        if not existe:
                            self.juegos[clave] = Videojuego(fila["titulo"])
                        self.agregar_ficha(clave, fila)
                        altas += int(not existe)
                        coincidencias += int(existe)
        if altas + coincidencias == 0:
            raise ValueError(f"{fuente.nombre} no tiene filas con título.")
        self.estadisticas[fuente.nombre] = (total, altas, coincidencias)

    def agregar_ficha(self, clave, fila):
        """Agrega rasgos de una fila estandarizada a la ficha de título clave."""
        juego = self.juegos[clave]
        if fila["identificador"].isascii() and fila["identificador"].isdigit():
            self.por_appid[fila["identificador"]] = clave
        plataformas = nombres_de_campo(fila["plataformas"])
        for campo, etiqueta in (("windows", "PC"), ("mac", "Mac"), ("linux", "Linux")):
            if normalizar(fila[campo]) in ("true", "yes", "1", "si"):
                plataformas.append(etiqueta)
        for plataforma in plataformas:
            if normalizar(plataforma) not in {"", "n a", "unknown"}:
                juego.plataformas.add(PLATAFORMAS_EQUIVALENTES.get(normalizar(plataforma), plataforma))
        anio = re.search(r"\b(?:19[5-9]\d|20\d{2})\b", fila["anio"])
        if anio:
            valor = int(anio.group())
            juego.anio = min(juego.anio or valor, valor)

        # Las facetas del segundo CSV enriquecen una ficha aunque ya exista.
        generos = {GENEROS_CSV.get(normalizar(g), g) for g in nombres_de_campo(fila["genero"])}
        generos = {g for g in generos if normalizar(g) not in {"", "n a", "unknown"}}
        temas = {normalizar(t) for t in etiquetas_de_campo(fila["etiquetas"])}
        if "horror" in temas:
            generos.add("Terror")
        if clave in TERROR_PSICOLOGICO or "psychological horror" in temas:
            generos.update(("Terror", "Terror psicológico"))
        saga_manual = next((s for s in SERIES_TERROR if clave == s or clave.startswith(s + " ")), "")
        if saga_manual or clave in TERROR_ADICIONAL:
            generos.add("Terror")
        saga = normalizar(fila["saga"])
        juego.saga = juego.saga or saga_manual or (saga if saga != "ninguna" else "")
        juego.generos.update(generos)
        juego.atributos.update(("genero", normalizar(g)) for g in generos)
        juego.atributos.update(("tema", t) for t in temas if t)
        if juego.saga:
            juego.atributos.add(("tema", juego.saga))
        for campo, tipo in (("desarrollador", "estudio"), ("editora", "editora")):
            nombres = [normalizar(v) for v in nombres_de_campo(fila[campo])[:4]]
            juego.atributos.update((tipo, n) for n in nombres if n not in {"", "n a", "unknown"})

        nota, opiniones, popularidad = resena_publica(fila)
        if nota is not None and opiniones > juego.evidencia_publica:
            juego.calidad_publica = nota
            juego.evidencia_publica = opiniones
        juego.popularidad = max(juego.popularidad, popularidad)

    def disponibles(self, plataforma):
        """Devuelve los títulos de la plataforma indicada, o todos con None."""
        filtro = normalizar(plataforma) if plataforma is not None else None
        filtro = normalizar(PLATAFORMAS_EQUIVALENTES.get(filtro, filtro)) if filtro is not None else None
        if filtro is not None and filtro not in self.plataformas:
            opciones = ", ".join(sorted(self.plataformas.values()))
            raise ValueError(f"Plataforma {plataforma!r} desconocida. Disponibles: {opciones}.")
        return [clave for clave, juego in self.juegos.items()
                if filtro is None or any(normalizar(p) == filtro for p in juego.plataformas)]


# %% Perfil local y señales de actividad

def crear_tablas(conexion, historial):
    """Inicializa SQLite para una persona y conserva las tablas del programa original."""
    conexion.executescript("""
        CREATE TABLE IF NOT EXISTS perfil (
            id INTEGER PRIMARY KEY CHECK (id=1), generos TEXT NOT NULL,
            favoritos TEXT NOT NULL, alta INTEGER NOT NULL, cuenta_steam TEXT,
            csv_con_historia_previa INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS actividad_steam (
            appid TEXT PRIMARY KEY, titulo TEXT NOT NULL, minutos INTEGER NOT NULL,
            ultima INTEGER NOT NULL, visitas INTEGER NOT NULL, base_minutos INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS actividad_csv (
            titulo TEXT PRIMARY KEY, sesiones INTEGER NOT NULL, base_sesiones INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS configuraciones (
            clave TEXT PRIMARY KEY, parametros TEXT NOT NULL
        );
    """)
    with conexion:
        conexion.execute("""
            INSERT OR IGNORE INTO perfil(id, generos, favoritos, alta, csv_con_historia_previa)
            VALUES(1, '[]', '[]', ?, ?)
        """, (int(time.time()), int(historial.is_file())))


def leer_vdf(ruta):
    """Devuelve el diccionario de un archivo de texto KeyValues de Steam."""
    arbol = {}
    pila = [arbol]
    clave = None
    for token in TOKENS_VDF.findall(ruta.read_text(encoding="utf-8-sig")):
        if token == "{":
            if clave is None:
                raise ValueError(f"Falta una clave en {ruta.name}.")
            rama = {}
            pila[-1][clave] = rama
            pila.append(rama)
            clave = None
        elif token == "}":
            if len(pila) < 2 or clave is not None:
                raise ValueError(f"Estructura incompleta en {ruta.name}.")
            pila.pop()
        elif not token.startswith("//"):
            valor = re.sub(r'\\(["\\])', r'\1', token[1:-1]) if token.startswith('"') else token
            if clave is None:
                clave = valor.casefold()
            else:
                pila[-1][clave] = valor
                clave = None
    if len(pila) != 1 or clave is not None:
        raise ValueError(f"Archivo incompleto: {ruta.name}.")
    return arbol


def ubicar_steam():
    """Busca una instalación local de Steam y devuelve su ruta o None."""
    personal = Path.home()
    rutas = [
        personal / "Library/Application Support/Steam", personal / ".steam/steam",
        personal / ".local/share/Steam",
        personal / ".var/app/com.valvesoftware.Steam/data/Steam",
    ]
    rutas.extend(Path(os.environ[v]) / "Steam" for v in ("ProgramFiles(x86)", "ProgramFiles")
                 if os.environ.get(v))
    if CARPETA_STEAM is not None:
        rutas = [Path(CARPETA_STEAM).expanduser()]
    return next((ruta for ruta in rutas if (ruta / "userdata").is_dir()), None)


def seleccionar_cuenta(raiz):
    """Devuelve la cuenta más reciente o la única cuenta local reconocible."""
    archivo = raiz / "config/loginusers.vdf"
    actuales = []
    if archivo.is_file():
        usuarios = leer_vdf(archivo).get("users", {})
        if isinstance(usuarios, dict):
            actuales = [str(int(k) & 0xFFFFFFFF) for k, v in usuarios.items()
                        if k.isascii() and k.isdigit() and isinstance(v, dict)
                        and v.get("mostrecent") == "1"]
    cuentas = [p.parent.parent.name for p in (raiz / "userdata").glob("*/config/localconfig.vdf")
               if p.parent.parent.name.isascii() and p.parent.parent.name.isdigit()
               and p.parent.parent.name != "0"]
    candidatas = actuales or cuentas
    return candidatas[0] if len(candidatas) == 1 else None


def nombres_instalados(raiz, catalogo):
    """Asocia identificadores con títulos del catálogo usando manifiestos locales."""
    carpetas = {raiz / "steamapps"}
    indice = raiz / "steamapps/libraryfolders.vdf"
    if indice.is_file():
        bibliotecas = leer_vdf(indice).get("libraryfolders", {})
        if isinstance(bibliotecas, dict):
            for clave, valor in bibliotecas.items():
                direccion = valor.get("path") if isinstance(valor, dict) else valor
                if clave.isdigit() and isinstance(direccion, str) and direccion:
                    carpetas.add(Path(direccion) / "steamapps")
    nombres = {}
    for carpeta in sorted(carpetas):
        for manifiesto in sorted(carpeta.glob("appmanifest_*.acf")):
            try:
                datos = leer_vdf(manifiesto).get("appstate", {})
                if isinstance(datos, dict):
                    titulo = clave_titulo(str(datos.get("name", "")))
                    appid = datos.get("appid", "")
                    if titulo in catalogo.juegos and isinstance(appid, str) and appid.isdigit():
                        nombres[appid] = titulo
            except (OSError, ValueError):
                # Se puede releer un manifiesto que Steam esté reemplazando.
                print(f"Steam omitió {manifiesto.name} en esta lectura.")
    return nombres


def registros_steam(archivo, raiz, catalogo, anteriores):
    """Extrae minutos y última partida de los identificadores reconocidos."""
    apps = leer_vdf(archivo)
    for clave in ("userlocalconfigstore", "software", "valve", "steam", "apps"):
        apps = apps.get(clave, {}) if isinstance(apps, dict) else {}
    registros = []
    if isinstance(apps, dict):
        instalados = nombres_instalados(raiz, catalogo)
        for appid, datos in apps.items():
            titulo = catalogo.por_appid.get(appid) or instalados.get(appid) or anteriores.get(appid)
            if titulo in catalogo.juegos and isinstance(datos, dict):
                tiempo = str(datos.get("playtime", ""))
                marca = str(datos.get("lastplayed", ""))
                minutos = int(tiempo) if tiempo.isascii() and tiempo.isdigit() else 0
                fecha = int(marca) if marca.isascii() and marca.isdigit() else 0
                if fecha == 86400:  # Marca histórica para una fecha desconocida.
                    fecha = 0
                if minutos or fecha:
                    registros.append((appid, titulo, minutos, fecha))
    return registros


def sincronizar_steam(conexion, catalogo):
    """Lee una sola cuenta de Steam y guarda máximos acumulados en una transacción."""
    raiz = ubicar_steam()
    mensaje = ""
    if raiz is not None:
        guardada, = conexion.execute("SELECT cuenta_steam FROM perfil WHERE id=1").fetchone()
        cuenta = guardada or seleccionar_cuenta(raiz)
        if cuenta and cuenta.isascii() and cuenta.isdigit():
            archivo = raiz / "userdata" / cuenta / "config/localconfig.vdf"
            if archivo.is_file():
                anteriores = dict(conexion.execute("SELECT appid, titulo FROM actividad_steam"))
                registros = registros_steam(archivo, raiz, catalogo, anteriores)
                with conexion:
                    cambio = conexion.execute("""
                        UPDATE perfil SET cuenta_steam=?
                        WHERE id=1 AND (cuenta_steam IS NULL OR cuenta_steam=?)
                    """, (cuenta, cuenta))
                    if cambio.rowcount:
                        conexion.executemany("""
                            INSERT INTO actividad_steam
                            (appid, titulo, minutos, ultima, visitas, base_minutos)
                            VALUES(?, ?, ?, ?, 1, 0)
                            ON CONFLICT(appid) DO UPDATE SET
                                titulo=excluded.titulo,
                                visitas=visitas+CAST(excluded.ultima>ultima AS INTEGER),
                                minutos=MAX(minutos, excluded.minutos),
                                ultima=MAX(ultima, excluded.ultima)
                        """, registros)
                        mensaje = f"Steam local · {len(registros)} títulos reconocidos."
    return mensaje


def importar_historial_csv(conexion, ruta, catalogo):
    """Guarda totales no negativos de titulo;sesiones y acepta el encabezado legado."""
    if ruta.is_file():
        totales = {}
        with ruta.open(encoding="utf-8-sig", newline="") as archivo:
            lector = csv.DictReader(archivo, delimiter=";")
            tiene_titulos = "titulo" in (lector.fieldnames or [])
            campos = set(lector.fieldnames or [])
            if "sesiones" not in campos or not ({"titulo", "identificador"} & campos):
                raise ValueError(f"{ruta.name} necesita columnas titulo;sesiones.")
            equivalencias = {}
            if not tiene_titulos:
                original = ruta.parent / "catalogo_videojuegos.csv"
                if original.is_file():
                    with original.open(encoding="utf-8-sig", newline="") as anterior:
                        equivalencias = {
                            fila["identificador"]: fila["titulo"]
                            for fila in csv.DictReader(anterior, delimiter=";")
                        }
                else:
                    equivalencias = catalogo.por_appid
            for indice, fila in enumerate(lector, 2):
                titulo = fila.get("titulo") if tiene_titulos else equivalencias.get(fila.get("identificador"))
                clave = clave_titulo(titulo or "")
                cantidad = (fila.get("sesiones") or "").strip()
                es_entero = cantidad.isascii() and cantidad.isdigit() and len(cantidad) <= 19
                if not clave or not es_entero or int(cantidad) >= 2 ** 63:
                    raise ValueError(f"Revisa el título y su total de sesiones en la fila {indice}.")
                totales[clave] = max(totales.get(clave, 0), int(cantidad))
        with conexion:
            # Leer el mismo archivo cada vez conserva el máximo, en vez de sumarlo.
            conexion.executemany("""
                INSERT INTO actividad_csv(titulo, sesiones, base_sesiones) VALUES(?, ?, 0)
                ON CONFLICT(titulo) DO UPDATE SET sesiones=MAX(sesiones, excluded.sesiones)
            """, [(clave, total) for clave, total in totales.items()
                  if clave in catalogo.juegos and total > 0])


@dataclass(frozen=True)
class Actividad:
    """Registros acumulados de un juego y marca de favorito del perfil anterior."""

    sesiones: int = 0
    minutos: int = 0
    favorito: bool = False

    @property
    def repetido(self):
        """Indica dos visitas, uso prolongado en Steam o un favorito previo."""
        return self.sesiones >= 2 or self.minutos >= 90 or self.favorito


def actividad_personal(conexion, catalogo):
    """Combina fuentes sin sumar dos veces las sesiones del mismo juego."""
    generos, favoritos = conexion.execute("SELECT generos, favoritos FROM perfil WHERE id=1").fetchone()
    actividad = {}
    for nombre, registros, minutos in conexion.execute("""
        SELECT titulo, MAX(visitas, 1), minutos FROM actividad_steam
            WHERE minutos>0 OR ultima>0
        UNION ALL SELECT titulo, sesiones, 0 FROM actividad_csv WHERE sesiones>0
    """):
        clave = clave_titulo(nombre)
        if clave in catalogo.juegos:
            previa = actividad.get(clave, Actividad())
            actividad[clave] = Actividad(max(registros, previa.sesiones), max(minutos, previa.minutos))
    for favorito in json.loads(favoritos):
        clave = clave_titulo(favorito)
        if clave in catalogo.juegos:
            actividad[clave] = replace(actividad.get(clave, Actividad()), favorito=True)
    return actividad, json.loads(generos)


@dataclass
class PerfilPreferencias:
    """Coeficientes por atributo, intercepto y cantidad de evidencia personal."""

    pesos: dict
    intercepto: float
    evidencia: float


def sigmoide(valor):
    """Convierte un valor real en una puntuación de 0 a 1 de forma estable."""
    exponencial = math.exp(-abs(valor))
    return 1 / (1 + exponencial) if valor >= 0 else exponencial / (1 + exponencial)


def ejemplos_aprendizaje(catalogo, actividad, repetidos, reservados):
    """Crea ejemplos de uso repetido y de referencia con pesos balanceados."""
    positivos = []
    referencia = []
    for clave in sorted(actividad):
        uso = actividad[clave]
        atributos = tuple(sorted(catalogo.juegos[clave].atributos))
        if clave in repetidos:
            # El logaritmo y el límite reducen el efecto de tiempos extremos.
            intensidad = 1 + min(2.0, math.log2(max(1, uso.sesiones, uso.minutos / 45)))
            positivos.append((atributos, intensidad))
        else:
            referencia.append((atributos, 1.0))

    # La muestra de fondo permite estimar qué distingue los juegos usados
    # respecto del catálogo. Es una referencia de oferta, con un peso acotado.
    fondo = [clave for clave in catalogo.juegos if clave not in actividad and clave not in reservados]
    muestra = random.Random(SEMILLA).sample(fondo, min(48, len(fondo)))
    if muestra:
        peso_fondo = max(1.0, len(referencia) / 3) / len(muestra)
        referencia.extend((tuple(sorted(catalogo.juegos[clave].atributos)), peso_fondo)
                          for clave in muestra)
    ejemplos = []
    if positivos and referencia:
        for clase, grupo in ((1, positivos), (0, referencia)):
            masa = sum(peso for _, peso in grupo)
            ejemplos.extend((atributos, clase, peso / (2 * masa))
                            for atributos, peso in grupo)
    return ejemplos


def aprender_perfil(catalogo, actividad, generos_guardados=(), reservados=frozenset()):
    """Entrena una regresión logística y reserva los títulos de prueba indicados."""
    repetidos = {clave for clave, uso in actividad.items() if uso.repetido}
    ejemplos = ejemplos_aprendizaje(catalogo, actividad, repetidos, reservados) if repetidos else []
    pesos = dict.fromkeys((rasgo for rasgos, _, _ in ejemplos for rasgo in rasgos), 0.0)
    intercepto = 0.0
    evidencia = 0.0

    # La penalización L2 reduce los coeficientes de rasgos poco respaldados.
    # Cada iteración mide el error ponderado y recalcula todos los coeficientes.
    if ejemplos:
        evidencia = sum(1 + min(2.0, math.log2(max(1, actividad[i].sesiones,
                                                  actividad[i].minutos / 45)))
                        for i in sorted(repetidos))
        for _ in range(70):
            gradientes = dict.fromkeys(pesos, 0.0)
            gradiente_intercepto = 0.0
            for rasgos, clase, peso in ejemplos:
                puntuacion = intercepto + sum(PESOS_ATRIBUTOS[r[0]] * pesos[r] for r in rasgos)
                estimado = sigmoide(puntuacion)
                error = peso * (estimado - clase)
                gradiente_intercepto += error
                for rasgo in rasgos:
                    gradientes[rasgo] += error * PESOS_ATRIBUTOS[rasgo[0]]
            intercepto -= 0.7 * gradiente_intercepto
            for rasgo in pesos:
                pesos[rasgo] -= 0.7 * (gradientes[rasgo] + 0.045 * pesos[rasgo])

    # Se conservan los géneros si la persona ya los guardó en la versión previa.
    for genero in generos_guardados:
        rasgo = ("genero", normalizar(genero))
        pesos[rasgo] = pesos.get(rasgo, 0) + 0.45
    return PerfilPreferencias(pesos, intercepto, evidencia + len(generos_guardados))


def estimar_afinidad(juego, perfil):
    """Mezcla la predicción logística y la referencia pública en [0, 1]."""
    valor = perfil.intercepto
    for rasgo in sorted(juego.atributos):
        valor += PESOS_ATRIBUTOS[rasgo[0]] * perfil.pesos.get(rasgo, 0)
    proporcion = min(0.90, perfil.evidencia / (1.5 + perfil.evidencia))
    return (1 - proporcion) * juego.referencia + proporcion * sigmoide(valor)


# %% Evolución de rutas

@dataclass(frozen=True)
class Configuracion:
    """Tamaño de población, descendientes por generación, torneo y mutación dirigida."""

    poblacion: int
    descendientes: int
    torneo: int
    dirigida: float


DOMINIO = {
    "poblacion": (12, 18, 24, 30, 36),
    "descendientes": (6, 9, 12, 15, 18, 24),
    "torneo": (2, 3, 4, 5),
    "dirigida": (0.20, 0.45, 0.70, 0.90),
}
BASE_COMPARACION = Configuracion(30, 18, 3, 0.45)


def configuracion_valida(configuracion):
    """Comprueba rangos, capacidad del torneo y espacio para el elitismo."""
    return (
        all(getattr(configuracion, clave) in valores for clave, valores in DOMINIO.items())
        and configuracion.torneo <= configuracion.poblacion
        and configuracion.descendientes < configuracion.poblacion <= PRESUPUESTO
    )


@dataclass(frozen=True)
class MedidasRuta:
    """Afinidad, variedad y continuidad de una ruta factible, todas en [0, 1]."""

    afinidad: float
    variedad: float
    continuidad: float

    @property
    def aptitud(self):
        """Pondera los tres criterios acordados para la ruta."""
        return 0.60 * self.afinidad + 0.20 * self.variedad + 0.20 * self.continuidad


class Problema:
    """Catálogo, candidatos ya filtrados y presupuesto de posiciones de una ruta."""

    def __init__(self, catalogo, candidatos, longitud, perfil):
        """Recibe claves distintas y longitud solicitada positiva."""
        self.catalogo = catalogo
        self.longitud = min(longitud, len(candidatos))
        self.afinidades = {
            clave: estimar_afinidad(catalogo.juegos[clave], perfil) for clave in candidatos
        }
        self.candidatos = tuple(sorted(candidatos, key=lambda i: (-self.afinidades[i], i)))
        self.parecido = lru_cache(maxsize=24000)(self.parecido_de_juegos)

    def parecido_de_juegos(self, a, b):
        """Devuelve similitud de Jaccard e indicador de saga para dos claves."""
        primero, segundo = self.catalogo.juegos[a], self.catalogo.juegos[b]
        union = primero.atributos | segundo.atributos
        similitud = len(primero.atributos & segundo.atributos) / len(union) if union else 0
        return similitud, bool(primero.saga and primero.saga == segundo.saga)

    def medir(self, ruta):
        """Evalúa una ruta válida y no vacía. Los pares consecutivos dan continuidad."""
        afinidad = sum(self.afinidades[i] for i in ruta) / len(ruta)
        variedad = continuidad = 1.0
        if len(ruta) > 1:
            suma_pares = suma_vecinos = 0.0
            for inicio, clave in enumerate(ruta[:-1]):
                for distancia, pareja in enumerate(ruta[inicio + 1:], 1):
                    similitud, misma_saga = self.parecido(*sorted((clave, pareja)))
                    suma_pares += similitud + 0.5 * misma_saga
                    if distancia == 1:
                        suma_vecinos += similitud
            total_pares = len(ruta) * (len(ruta) - 1) / 2
            variedad = max(0.0, 1 - suma_pares / total_pares)
            continuidad = suma_vecinos / (len(ruta) - 1)
        return MedidasRuta(afinidad, variedad, continuidad)


@dataclass(frozen=True)
class Resultado:
    """Mejor ruta encontrada y medidas del recorrido evolutivo."""

    ruta: tuple
    generacion: int             # Generación de la última mejora estricta.
    evaluacion_convergencia: int
    evaluaciones: int
    diversidad_genetica: float  # Distancia de Hamming promedio por generación.


def diversidad_genetica(poblacion):
    """Promedio de la fracción de genes distintos entre pares de rutas ordenadas."""
    cantidad = len(poblacion)
    genes = len(poblacion[0])
    diversidad = 0.0
    if cantidad > 1 and genes:
        iguales = sum(n * (n - 1) for columna in zip(*poblacion)
                      for n in Counter(columna).values())
        diversidad = 1 - iguales / (cantidad * (cantidad - 1) * genes)
    return diversidad


class EvolucionRutas:
    """Estrategia con elitismo y un solo padre por descendiente."""

    def __init__(self, problema, configuracion, semilla):
        """Recibe un problema factible, parámetros válidos y una semilla entera."""
        if not configuracion_valida(configuracion) or not problema.longitud:
            raise ValueError("La evolución requiere candidatos y una configuración válida.")
        self.problema = problema
        self.configuracion = configuracion
        self.azar = random.Random(semilla)
        self.candidatos = problema.candidatos
        self.longitud = problema.longitud
        self.preferidos = self.candidatos[:max(self.longitud + 1, 24)]

    def mutar(self, padre):
        """Genera una ruta válida por intercambio o sustitución de un solo título."""
        ruta = list(padre)
        hay_sustitutos = self.longitud < len(self.candidatos)
        intercambiar = self.longitud > 1 and (not hay_sustitutos or self.azar.random() < 0.28)
        if intercambiar:
            a, b = self.azar.sample(range(self.longitud), 2)
            ruta[a], ruta[b] = ruta[b], ruta[a]
        elif hay_sustitutos:
            dirigida = self.azar.random() < self.configuracion.dirigida
            opciones = self.preferidos if dirigida else self.candidatos
            ocupados = set(padre)
            if len(opciones) <= max(24, 2 * self.longitud):
                nuevo = self.azar.choice([i for i in opciones if i not in ocupados])
            else:
                nuevo = self.azar.choice(opciones)
                while nuevo in ocupados:
                    nuevo = self.azar.choice(opciones)
            ruta[self.azar.randrange(self.longitud)] = nuevo
        return tuple(ruta)

    def ejecutar(self):
        """Evoluciona una población válida con un presupuesto fijo de evaluaciones."""
        mejor = self.candidatos[:self.longitud]
        if len(self.candidatos) == 1:
            resultado = Resultado(mejor, 0, 1, 1, 0.0)
        else:
            resultado = self.evolucionar(mejor)
        return resultado

    def evolucionar(self, semilla_ruta):
        """Evoluciona desde la mejor afinidad individual y un conjunto de rutas al azar."""
        config = self.configuracion
        iniciales = [semilla_ruta] + [
            tuple(self.azar.sample(self.candidatos, self.longitud))
            for _ in range(config.poblacion - 1)
        ]
        poblacion = [(self.problema.medir(ruta).aptitud, ruta) for ruta in iniciales]
        mejor = max(poblacion, key=lambda par: par[0])
        evaluaciones = len(poblacion)
        evaluacion_mejor = poblacion.index(mejor) + 1
        generacion = generacion_mejor = 0
        diversidades = [diversidad_genetica(iniciales)]

        # Los mejores supervivientes se copian. Todo individuo nuevo se
        # evalúa una vez y procede de una mutación, con selección por torneo.
        while evaluaciones < PRESUPUESTO:
            generacion += 1
            cantidad = min(config.descendientes, PRESUPUESTO - evaluaciones)
            nueva = sorted(poblacion, key=lambda par: par[0], reverse=True)[:config.poblacion - cantidad]
            for _ in range(cantidad):
                torneo = self.azar.sample(poblacion, config.torneo)
                padre = max(torneo, key=lambda par: par[0])[1]
                hijo = self.mutar(padre)
                candidato = (self.problema.medir(hijo).aptitud, hijo)
                nueva.append(candidato)
                evaluaciones += 1
                if candidato[0] > mejor[0] + 1e-12:
                    mejor = candidato
                    generacion_mejor = generacion
                    evaluacion_mejor = evaluaciones
            poblacion = nueva
            diversidades.append(diversidad_genetica([ruta for _, ruta in poblacion]))
        return Resultado(mejor[1], generacion_mejor, evaluacion_mejor, evaluaciones,
                         statistics.mean(diversidades))


# %% Ajuste de parámetros y experimento

@dataclass
class Escenario:
    """Perfil aprendido con un subconjunto de juegos y gustos ocultos de prueba."""

    problema: Problema
    gusto_oculto: dict
    semilla: int


def generar_escenarios(catalogo, disponibles, longitud, cantidad, semilla):
    """Genera problemas simulados con juegos de entrenamiento y prueba disjuntos."""
    origen = random.Random(semilla)
    escenarios = []
    for _ in range(cantidad):
        azar = random.Random(origen.getrandbits(64))
        # Hasta 500 candidatos reproducibles por plataforma o catálogo.
        muestra = azar.sample(disponibles, min(514, len(disponibles)))
        total_observados = min(14, max(0, len(muestra) - longitud))
        observados = muestra[:total_observados]
        candidatos = muestra[total_observados:]
        frecuencias = Counter(normalizar(g) for i in muestra for g in catalogo.juegos[i].generos)
        frecuentes = sorted(g for g, n in frecuencias.items() if n >= min(6, len(muestra)))
        preferidos = set(azar.sample(frecuentes, min(2, len(frecuentes))))

        # El experimento conoce una probabilidad oculta de repetir cada juego.
        # El recomendador recibe únicamente las sesiones de los juegos observados.
        gustos = {}
        for clave in muestra:
            juego = catalogo.juegos[clave]
            coincide = any(normalizar(g) in preferidos for g in juego.generos)
            ventaja = 0.45 if coincide else 0.0
            gustos[clave] = 0.12 + ventaja + 0.22 * juego.calidad_publica + azar.uniform(0, 0.12)
        actividad = {
            i: Actividad(azar.randint(2, 6) if azar.random() < gustos[i] else 1)
            for i in observados
        }
        perfil = aprender_perfil(catalogo, actividad, reservados=set(candidatos))
        problema = Problema(catalogo, candidatos, longitud, perfil)
        escenarios.append(Escenario(problema, {i: gustos[i] for i in candidatos}, azar.getrandbits(64)))
    return escenarios


def gusto_de_ruta(escenario, ruta):
    """Devuelve el interés medio oculto, reservado para medir una ruta de prueba."""
    return statistics.mean(escenario.gusto_oculto[i] for i in ruta)


def aptitud_configuracion(configuracion, escenarios):
    """Combina calidad externa, diversidad genética y rapidez de convergencia."""
    resultados = []
    for escenario in escenarios:
        problema = escenario.problema
        resultado = EvolucionRutas(problema, configuracion, escenario.semilla).ejecutar()
        medidas = problema.medir(resultado.ruta)
        calidad = 0.75 * gusto_de_ruta(escenario, resultado.ruta)
        calidad += 0.15 * medidas.variedad + 0.10 * medidas.continuidad
        rapidez = 1 - resultado.evaluacion_convergencia / resultado.evaluaciones
        resultados.append(0.84 * calidad + 0.10 * resultado.diversidad_genetica + 0.06 * rapidez)
    return statistics.mean(resultados)


def mutar_configuracion(padre, azar):
    """Cambia un solo parámetro por otro valor válido de su dominio."""
    alternativas = []
    for campo, valores in DOMINIO.items():
        for valor in valores:
            if valor != getattr(padre, campo):
                vecina = replace(padre, **{campo: valor})
                if configuracion_valida(vecina):
                    alternativas.append(vecina)
    return azar.choice(alternativas)


def ajustar_parametros(escenarios, semilla):
    """Evoluciona configuraciones mediante mutación y selección por torneo."""
    azar = random.Random(semilla)
    posibles = [config for valores in product(*DOMINIO.values())
                if configuracion_valida(config := Configuracion(*valores))
                and config != BASE_COMPARACION]
    poblacion = [BASE_COMPARACION] + azar.sample(posibles, 4)
    notas = {}

    # Una configuración repetida siempre usa los mismos problemas y semillas.
    # El diccionario evita repetir una evaluación determinista del experimento.
    for generacion in range(5):
        for config in poblacion:
            if config not in notas:
                notas[config] = aptitud_configuracion(config, escenarios)
        mejor = max(poblacion, key=notas.get)
        if generacion < 4:
            hijos = []
            for _ in range(len(poblacion) - 1):
                padre = max(azar.sample(poblacion, 2), key=notas.get)
                hijos.append(mutar_configuracion(padre, azar))
            poblacion = [mejor] + hijos
    return mejor, notas[mejor], len(notas)


def parametros_para_recomendar(conexion, catalogo, candidatos, longitud, plataforma, semilla):
    """Recupera o ajusta los parámetros del catálogo y filtro de la ruta."""
    firma = [VERSION_AJUSTE, plataforma, longitud, semilla, [f.firma() for f in catalogo.fuentes]]
    clave = json.dumps(firma, ensure_ascii=False)
    fila = conexion.execute("SELECT parametros FROM configuraciones WHERE clave=?", (clave,)).fetchone()
    if fila is None:
        print("Ajustando el evolutivo con escenarios simulados. Se guarda para las siguientes ejecuciones.")
        escenarios = generar_escenarios(catalogo, candidatos, longitud, 6, semilla + 1000)
        parametros, _, _ = ajustar_parametros(escenarios, semilla + 2000)
        with conexion:
            conexion.execute("INSERT OR IGNORE INTO configuraciones VALUES (?, ?)",
                             (clave, json.dumps(asdict(parametros))))
        fila = conexion.execute("SELECT parametros FROM configuraciones WHERE clave=?", (clave,)).fetchone()
    return Configuracion(**json.loads(fila[0]))


def fila_de_prueba(escenario, numero_prueba, metodo, ruta, segundos, evolucion=None):
    """Devuelve observaciones de una prueba, con campos evolutivos cuando aplican."""
    problema = escenario.problema
    medidas = problema.medir(ruta)
    violaciones = abs(problema.longitud - len(ruta))
    violaciones += len(ruta) - len(set(ruta))
    violaciones += sum(i not in problema.afinidades for i in ruta)
    return {
        "prueba": numero_prueba, "semilla": escenario.semilla, "metodo": metodo,
        "afinidad": medidas.afinidad, "variedad": medidas.variedad,
        "continuidad": medidas.continuidad, "aptitud": medidas.aptitud,
        "interes_simulado": gusto_de_ruta(escenario, ruta), "violaciones": violaciones,
        "segundos_busqueda": segundos,
        "generacion_convergencia": evolucion.generacion if evolucion is not None else None,
        "evaluaciones_convergencia": evolucion.evaluacion_convergencia if evolucion is not None else None,
        "evaluaciones": evolucion.evaluaciones if evolucion is not None else 0,
        "diversidad_genetica": evolucion.diversidad_genetica if evolucion is not None else None,
        "ruta": json.dumps([problema.catalogo.juegos[i].titulo for i in ruta], ensure_ascii=False),
    }


def comparar_estrategias(escenarios, parametros):
    """Corre cuatro estrategias sobre los mismos candidatos y con semillas emparejadas."""
    resultados = []
    for numero_prueba, escenario in enumerate(escenarios, 1):
        problema = escenario.problema
        inicio = time.perf_counter()
        popularidad = sorted(problema.candidatos,
                             key=lambda i: (-problema.catalogo.juegos[i].referencia, i))
        ruta = tuple(popularidad[:problema.longitud])
        resultados.append(fila_de_prueba(escenario, numero_prueba, "Popularidad", ruta,
                                        time.perf_counter() - inicio))
        inicio = time.perf_counter()
        ruta = problema.candidatos[:problema.longitud]
        resultados.append(fila_de_prueba(escenario, numero_prueba, "Afinidad", ruta,
                                        time.perf_counter() - inicio))
        for metodo, configuracion in (("Evolutivo fijo", BASE_COMPARACION),
                                      ("Evolutivo ajustado", parametros)):
            inicio = time.perf_counter()
            resultado = EvolucionRutas(problema, configuracion, escenario.semilla).ejecutar()
            resultados.append(fila_de_prueba(escenario, numero_prueba, metodo, resultado.ruta,
                                            time.perf_counter() - inicio, resultado))
    return resultados


def parametros_en_texto(configuracion):
    """Representa en español una configuración evolutiva válida."""
    return (f"{configuracion.poblacion} rutas por población, "
            f"{configuracion.descendientes} descendientes, "
            f"torneo de {configuracion.torneo}, "
            f"{configuracion.dirigida:.0%} de sustituciones dirigidas")


def mostrar_resultados(resultados):
    """Imprime media y desviación estándar de cada estrategia en las pruebas."""
    grupos = defaultdict(list)
    for fila in resultados:
        grupos[fila["metodo"]].append(fila)
    medidas = (
        ("Interés simulado", "interes_simulado"),
        ("Aptitud de la ruta", "aptitud"),
        ("Variedad de la ruta", "variedad"),
        ("Continuidad de la ruta", "continuidad"),
        ("Diversidad genética", "diversidad_genetica"),
        ("Generación de convergencia", "generacion_convergencia"),
        ("Evaluación de convergencia", "evaluaciones_convergencia"),
        ("Evaluaciones totales", "evaluaciones"),
        ("Tiempo de búsqueda (s)", "segundos_busqueda"),
        ("Violaciones", "violaciones"),
    )
    print(f"\n{len(next(iter(grupos.values())))} pruebas · media ± desviación estándar.")
    print(f"{'Medida':<28}" + "".join(f"{metodo:>21}" for metodo in grupos))
    for etiqueta, columna in medidas:
        celdas = []
        for filas in grupos.values():
            valores = [fila[columna] for fila in filas if fila[columna] is not None]
            celda = "—"
            if valores:
                desviacion = statistics.stdev(valores) if len(valores) > 1 else 0.0
                celda = f"{statistics.mean(valores):.3f} ± {desviacion:.3f}"
            celdas.append(f"{celda:>21}")
        print(f"{etiqueta:<28}" + "".join(celdas))


def ejecutar_experimento(catalogo, candidatos, longitud, semilla, salida):
    """Ajusta con seis escenarios y evalúa otros cincuenta. Guarda una fila por ruta."""
    entrenamiento = generar_escenarios(catalogo, candidatos, longitud, 6, semilla + 1000)
    elegido, aptitud, probadas = ajustar_parametros(entrenamiento, semilla + 2000)
    print(f"Se evaluaron {probadas} configuraciones con 6 escenarios de ajuste.")
    print(f"Parámetros ajustados · {parametros_en_texto(elegido)}.")
    print(f"Aptitud del ajuste · {aptitud:.3f}.")
    casos_nuevos = generar_escenarios(catalogo, candidatos, longitud, REPETICIONES, semilla + 3000)
    resultados = comparar_estrategias(casos_nuevos, elegido)
    mostrar_resultados(resultados)
    guardar_resultados(resultados, salida)
    print(f"\nResultados por ejecución en {salida}.")
    return resultados


def guardar_resultados(resultados, salida):
    """Escribe el CSV completo antes de sustituir un resultado anterior."""
    archivo = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8-sig", newline="",
                                          dir=salida.parent, delete=False)
    temporal = Path(archivo.name)
    try:
        with archivo:
            escritor = csv.DictWriter(archivo, fieldnames=list(resultados[0]))
            escritor.writeheader()
            escritor.writerows(resultados)
        temporal.replace(salida)
    finally:
        temporal.unlink(missing_ok=True)


# %% Presentación de la ruta y modos de ejecución

def nombrar_atributo(juego, atributo):
    """Devuelve el nombre visible de un género o tema de la ficha."""
    tipo, valor = atributo
    nombre = valor
    if tipo == "genero":
        nombre = next((g for g in sorted(juego.generos) if normalizar(g) == valor), valor)
    return nombre


def mostrar_ruta(problema, resultado, perfil):
    """Imprime títulos, afinidad, razones por juego y continuidad entre vecinos."""
    catalogo = problema.catalogo
    medidas = problema.medir(resultado.ruta)
    print(f"\nRuta de {len(resultado.ruta)} videojuegos · aptitud {medidas.aptitud:.3f}")
    print(f"Afinidad {medidas.afinidad:.3f} · variedad {medidas.variedad:.3f}"
          f" · continuidad {medidas.continuidad:.3f}")
    anterior = None
    for posicion, clave in enumerate(resultado.ruta, 1):
        juego = catalogo.juegos[clave]
        plataformas = ", ".join(sorted(juego.plataformas)) or "plataforma sin registrar"
        anio = f" ({juego.anio})" if juego.anio else ""
        print(f"  {posicion}. {juego.titulo}{anio} · {plataformas}"
              f" · afinidad {problema.afinidades[clave]:.3f}")
        motivos = [r for r in juego.atributos if perfil.pesos.get(r, 0) > 0.05]
        motivos.sort(key=lambda r: (-perfil.pesos[r] * PESOS_ATRIBUTOS[r[0]], r))
        if motivos:
            relacionados = ", ".join(dict.fromkeys(nombrar_atributo(juego, r) for r in motivos[:2]))
            print(f"     El perfil favorece rasgos como {relacionados}.")
        elif perfil.evidencia:
            print("     Su afinidad y sus transiciones aportan a la puntuación de la ruta.")
        else:
            print("     La afinidad inicial se basa en reseñas y popularidad públicas.")
        if anterior is not None:
            pares = sorted(anterior.atributos & juego.atributos,
                           key=lambda r: (-PESOS_ATRIBUTOS[r[0]], r))
            if pares:
                relacion = ", ".join(dict.fromkeys(nombrar_atributo(juego, r) for r in pares[:2]))
                print(f"     Comparte {relacion} con el título anterior.")
            else:
                print("     Aporta una transición hacia rasgos diferentes.")
        anterior = juego


def ejecutar_demo(catalogo, candidatos, longitud, semilla):
    """Muestra dos rutas con los mismos candidatos y diferente actividad ficticia."""
    sesiones = {
        "resident evil 2": Actividad(6),
        "silent hill 2": Actividad(4),
        "rocket league": Actividad(1),
    }
    actividad = {clave: uso for clave, uso in sesiones.items() if clave in catalogo.juegos}
    nuevos = [clave for clave in candidatos if clave not in actividad]
    if len(actividad) < 2 or not nuevos:
        raise ValueError("La demostración requiere los títulos de ejemplo del catálogo incluido.")
    escenarios = generar_escenarios(catalogo, candidatos, longitud, 6, semilla + 1000)
    parametros, _, _ = ajustar_parametros(escenarios, semilla + 2000)
    for mensaje, datos in (("Antes de observar partidas", {}), ("Después de observar partidas", actividad)):
        print(f"\nSimulación · {mensaje}.")
        if datos:
            for clave, uso in datos.items():
                print(f"  {catalogo.juegos[clave].titulo} · {uso.sesiones} sesión(es)")
        perfil = aprender_perfil(catalogo, datos)
        problema = Problema(catalogo, nuevos, longitud, perfil)
        mostrar_ruta(problema, EvolucionRutas(problema, parametros, semilla).ejecutar(), perfil)


def recomendar(catalogo, candidatos, opciones):
    """Sincroniza el perfil y presenta una ruta nueva sin solicitar entradas."""
    historial = opciones.carpeta / "historial_juego.csv"
    with closing(sqlite3.connect(opciones.perfil, timeout=10)) as conexion:
        crear_tablas(conexion, historial)
        if not opciones.sin_steam:
            try:
                mensaje = sincronizar_steam(conexion, catalogo)
                if mensaje:
                    print(mensaje)
            except (OSError, ValueError) as error:
                print(f"No se pudo leer Steam local en esta ejecución. {error}")
        try:
            importar_historial_csv(conexion, historial, catalogo)
        except (OSError, ValueError, csv.Error) as error:
            print(f"No se pudo leer {historial.name} en esta ejecución. {error}")
        actividad, generos = actividad_personal(conexion, catalogo)
        nuevos = [clave for clave in candidatos if clave not in actividad]
        if nuevos:
            parametros = parametros_para_recomendar(
                conexion, catalogo, candidatos, opciones.longitud, opciones.plataforma, opciones.semilla,
            )
            perfil = aprender_perfil(catalogo, actividad, generos)
            problema = Problema(catalogo, nuevos, opciones.longitud, perfil)
            if perfil.evidencia:
                print(f"Perfil aprendido de la actividad disponible en {len(actividad)} títulos.")
            else:
                print("Arranque con puntuaciones públicas. La personalización se activa al observar uso recurrente.")
            resultado = EvolucionRutas(problema, parametros, opciones.semilla).ejecutar()
            mostrar_ruta(problema, resultado, perfil)
        else:
            print("Ya observaste actividad en todos los títulos disponibles para este filtro.")


def leer_opciones(argumentos=None):
    """Valida opciones de la terminal. Sin argumentos usa las opciones de Spyder."""
    analizador = argparse.ArgumentParser(description="Recomendador evolutivo de videojuegos.")
    analizador.add_argument("--modo", choices=("recomendar", "demo", "experimento", "catalogo"),
                           default=MODO)
    analizador.add_argument("--plataforma", default=PLATAFORMA, help="Por ejemplo, PS4 o PC.")
    analizador.add_argument("--longitud", type=int, default=LONGITUD_RUTA, metavar="N",
                           help="Cantidad positiva de juegos. Valor inicial: 5.")
    analizador.add_argument("--carpeta", type=Path, default=CARPETA_BASE,
                           help="Carpeta existente de los archivos complementarios.")
    analizador.add_argument("--perfil", type=Path, help="Ruta de la base local del jugador.")
    analizador.add_argument("--sin-steam", action="store_true", default=not USAR_STEAM,
                           help="Usa únicamente el historial CSV y el perfil guardado.")
    analizador.add_argument("--semilla", type=int, default=SEMILLA,
                           help="Semilla del generador para repetir una ejecución.")
    opciones = analizador.parse_args(argumentos)
    if opciones.longitud < 1:
        analizador.error("--longitud debe ser un entero positivo")
    if not opciones.carpeta.is_dir():
        analizador.error("--carpeta debe ser una carpeta existente")
    if opciones.perfil is None:
        opciones.perfil = opciones.carpeta / "perfil_jugador.sqlite3"
    return opciones


def principal(argumentos=None):
    """Carga las fuentes, aplica el filtro de plataforma y ejecuta el modo elegido."""
    opciones = leer_opciones(argumentos)
    catalogo = Catalogo(localizar_catalogos(opciones.carpeta))
    candidatos = catalogo.disponibles(opciones.plataforma)
    for nombre, (filas, nuevos, coincidencias) in catalogo.estadisticas.items():
        print(f"{nombre} · {filas:,} filas, {nuevos:,} títulos nuevos, {coincidencias:,} coincidencias.")
    print(f"{len(candidatos):,} títulos para la plataforma elegida de {len(catalogo.juegos):,} en total.")
    if opciones.modo == "catalogo":
        print("Plataformas disponibles · " + ", ".join(sorted(catalogo.plataformas.values())))
    elif opciones.modo == "demo":
        ejecutar_demo(catalogo, candidatos, opciones.longitud, opciones.semilla)
    elif opciones.modo == "experimento":
        ejecutar_experimento(catalogo, candidatos, opciones.longitud, opciones.semilla,
                             opciones.carpeta / "resultados_experimento.csv")
    else:
        recomendar(catalogo, candidatos, opciones)


